import java.util.*;
import java.io.*;

public class Main {
    static List<int[]> solveNQueens(int n) {
        // Return every valid placement as 1-indexed columns (one per row),
        // sorted in lexicographic order.
        // Write your solution here
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), k = sc.nextInt();
        List<int[]> sols = solveNQueens(n);
        StringBuilder sb = new StringBuilder();
        sb.append(sols.size()).append("\n");
        for (int i = 0; i < sols.size() && i < k; i++) {
            int[] s = sols.get(i);
            for (int j = 0; j < s.length; j++) sb.append(s[j]).append(j + 1 < s.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
